"use strict";export const NOT_MODIFIED=Symbol("not modified");export class PollCache{constructor(){this.etags={};this.bodies={}}storeBody(url,body){this.bodies[url]=body}getBody(url){return this.bodies[url]}hasBody(url){return url in this.bodies}storeEtag(url,etag){if(etag){this.etags[url]=etag}}getEtag(url){return this.etags[url]}requestHeaders(url,baseheaders){const headers={...baseheaders};if(url in this.etags&&this.hasBody(url)){headers["If-None-Match"]=this.etags[url]}return headers}noteResponse(url,status,etag){this.storeEtag(url,etag);return status===304?NOT_MODIFIED:null}}
